int main() {
    try {
        const auto &tables = sobol_tables();
        for (const auto &answer : answers) {
            const auto &q = answer.q;
            const auto kind = q[0];
            const auto w = unsigned(q[1]), h = unsigned(q[2]), x = unsigned(q[3]),
                       y = unsigned(q[4]);
            const auto sample = std::uint64_t(q[5]);
            const auto d = unsigned(q[6]), mode = unsigned(q[7]), seed = unsigned(q[8]),
                       spp = unsigned(q[9]);
            std::array<std::uint64_t, 6> actual{};
            if (kind == 2) {
                const auto index = qmc::halton_index(w, h, x, y, sample);
                actual = {0,
                          qmc::float_bits(qmc::halton_camera(0, w, index)),
                          qmc::float_bits(qmc::halton_camera(1, h, index)),
                          qmc::float_bits(qmc::radical(d, index, mode, seed)),
                          qmc::float_bits(qmc::radical(d, index, mode, seed)),
                          qmc::float_bits(qmc::radical(d + 1, index, mode, seed))};
            } else {
                const auto m = sobol_scale_exponent(w, h);
                const auto log = std::bit_width(spp) - 1;
                const auto morton = qmc::morton(x, y, log, sample);
                actual = {qmc::zindex(morton, d, m, log),
                          qmc::float_bits(sobol::uniform(
                              qmc::zword(tables, morton, 1, 0, true, m, log, mode, seed))),
                          qmc::float_bits(sobol::uniform(
                              qmc::zword(tables, morton, 1, 1, true, m, log, mode, seed))),
                          qmc::float_bits(sobol::uniform(
                              qmc::zword(tables, morton, d, 0, false, m, log, mode, seed))),
                          qmc::float_bits(sobol::uniform(
                              qmc::zword(tables, morton, d, 0, true, m, log, mode, seed))),
                          qmc::float_bits(sobol::uniform(
                              qmc::zword(tables, morton, d, 1, true, m, log, mode, seed)))};
            }
            require(actual == answer.a, "Pinned PBRT QMC known answer mismatch");
        }
        RenderSampler h{SamplerKind::halton, SobolRandomization::permutedigits};
        RenderSampler z{SamplerKind::zsobol, SobolRandomization::fastowen};
        require(validate_sampler_range(h, UINT64_MAX, 257, 73, UINT64_C(1) << 32, 257).empty(),
                "Halton wide absolute index");
        require(!validate_sampler_range(h, 0, 128, 128, INT64_MAX, 1).empty(),
                "Halton overflow accepted");
        require(!validate_sampler_range({SamplerKind::halton, SobolRandomization::fastowen}, 0, 1,
                                        1, 0, 1)
                     .empty(),
                "Halton fastowen accepted");
        require(!validate_sampler_range(h, 0xffffffff, 1, 1, 0, 1).empty(),
                "Noncanonical Halton seed accepted");
        require(validate_sampler_range(z, 0, 3, 5, 0, 16, 16).empty(), "ZSobol valid range");
        require(!validate_sampler_range(z, 0, 3, 5, 0, 1).empty(), "ZSobol absent budget accepted");
        require(!validate_sampler_range(z, 0, 3, 5, 15, 2, 16).empty(),
                "ZSobol aliased sample accepted");
        require(!validate_sampler_range(z, 0, 3, 5, 0, 1, 17).empty(),
                "ZSobol nonpower budget accepted");
        require(validate_sampler_range(z, 0, 1u << 25, 1, 0, 4, 4).empty(),
                "ZSobol boundary capacity rejected");
        require(!validate_sampler_range(z, 0, 1u << 25, 1, 0, 4, 8).empty(),
                "ZSobol 52-bit overflow accepted");
        require(validate_sampler_range(z, 0, 1u << 26, 1, 0, 1, 1).empty(),
                "ZSobol 26-bit Morton boundary rejected");
        require(sampler_max_depth(h, false) == 124 && sampler_max_depth(h, true) == 110,
                "Halton depth domains");
        require(sampler_max_depth(z, false) == 127 && sampler_max_depth(z, true) == 113,
                "ZSobol depth domains");
        for (unsigned d : {2u, 7u, 883u, 884u, 993u, 998u, 999u}) {
            const auto index = qmc::halton_index(257, 73, 234, 71, 12345);
            require(qmc::radical(d, index, 3, 0) == qmc::radical(d, index, 3, 123),
                    "Halton Owen seed should be inert");
            require(qmc::radical(d, index, 0, 0) == qmc::radical(d, index, 0, 123),
                    "Halton none seed should be inert");
        }
        // Primary values below a 32-bit fixed-point grid must survive unchanged.
        require(qmc::radical(0, UINT64_C(1) << 40) > 0 &&
                    qmc::radical(0, UINT64_C(1) << 40) < 0x1p-32f,
                "Halton tiny camera fraction");
        std::cout << std::size(answers) << " pinned QMC vectors and range contracts passed\n";
        return 0;
    } catch (const std::exception &e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
